import {defaultState,clone,validateState,uid,mod,bonus,proficiency,clamp,applyHP,spendSlot,longRest,shortRest,buildContext,contextNotes,logAction,ABILITIES,ABILITY_NAMES,SKILLS,CONDITIONS} from './model.js';
import {FirebaseStore,friendlyFirebaseError} from './firebase.js';
import {firebaseConfig} from './firebase-config.js';
const $=(s,root=document)=>root.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sheet:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7',spark:'m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8Z',book:'M3 5c3-1 6-1 9 1 3-2 6-2 9-1v15c-3-1-6-1-9 1-3-2-6-2-9-1z M12 6v15',journal:'M5 3h14v18H5z M8 3v18 M11 8h5 M11 12h5 M11 16h3',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z',heart:'M20.8 4.6c-2.3-2.1-5.9-1.7-8.8 1.6C9.1 2.9 5.5 2.5 3.2 4.6.1 7.5 2.6 12.2 12 20c9.4-7.8 11.9-12.5 8.8-15.4Z',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',boot:'M6 3h8v8l6 4v5H4v-7h2z M6 7h5 M6 10h5 M4 17h16',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 11v2 M11 12h2',hammer:'m14 3 7 7-4 4-3-3-9 10-3-3 10-9-3-3z M7 5l3-3 3 1 M16 15l4 4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1.5 1.5 M17.5 17.5 19 19 M19 5l-1.5 1.5 M6.5 17.5 5 19',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',edit:'m15 4 5 5 M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15Z',close:'m6 6 12 12 M18 6 6 18',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',undo:'M9 4 4 9l5 5 M4 9h10a6 6 0 0 1 0 12',check:'m5 12 4 4L19 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2',cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5.5 5.5 0 1 1 0 11Z',copy:'M9 8h11v13H9z M15 8V3H4v13h5',external:'M14 3h7v7 M21 3 11 13 M10 3H3v18h18v-7',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 m5 12 6 6',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',pin:'m8 3 8 0-1 7 4 4H5l4-4z M12 14v7',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',scroll:'M5 3h12v14h4v2a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V5H2V3z M9 7h5 M9 11h5',star:'m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4L2.8 9.7l6.4-.9Z'};
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.spark}"/></svg>`;
const action=(id,label,{type='',iconName='',extra='',disabled=false}={})=>`<button type="button" class="btn ${type}" data-action="${id}" ${extra} ${disabled?'disabled':''}>${iconName?icon(iconName):''}${label}</button>`;
const views=[['sheet','sheet','Character'],['spells','book','Spellbook'],['journal','journal','Journal'],['ask','spark','Ask ChatGPT']];
const storagePrefix='rivet:v1:';
let storageFault='',account=null,envelope,storeKey=storagePrefix+'guest',history=[],cloudReady=false,cloudWriting=false,cloudConflict=null,cloudStatus='Saved on this device',cloudError='',syncTimer,toastTimer,localGeneration=0,modalReturnFocus=null;
let outgoingPayload=null,authGeneration=0,clearingLocal=false;
let config=firebaseConfig;
try{config=JSON.parse(localStorage.getItem(storagePrefix+'firebase')||'null')||firebaseConfig;}catch{}
function readEnvelope(key) {
  try{const raw=localStorage.getItem(key);if(!raw)return null;const env=JSON.parse(raw);validateState(env.state);if(!Number.isSafeInteger(env.revision)||env.revision<0)throw new Error('Invalid sync metadata.');return env;}
  catch(error){storageFault='An unreadable local save was found. Export a recovery copy in Connections before saving.';return null;}
}
envelope=readEnvelope(storeKey)||{state:defaultState(),revision:0,pending:false};
let state=envelope.state;
const ui={view:['sheet','spells','journal','ask','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'sheet',spellSearch:'',spellLevel:'all',preparedOnly:false,noteDraft:'',noteTag:'Story',question:'',includeNotes:true,concise:true,preparedText:'',hpAmount:5};
const session=()=>state.sessions.find(s=>s.id===state.activeSession);
const draftKey=()=>storeKey+':draft:'+state.activeSession;
function restoreDraft(){try{const d=JSON.parse(localStorage.getItem(draftKey())||'{}');ui.noteDraft=d.note||'';ui.question=d.question||'';}catch{ui.noteDraft='';ui.question='';}}
function saveDraft(){if(clearingLocal)return;try{localStorage.setItem(draftKey(),JSON.stringify({note:ui.noteDraft,question:ui.question}));}catch{toast('Draft could not be saved. Keep this tab open.');}}
restoreDraft();
function persist(){if(clearingLocal)return true;envelope.state=state;try{if(storageFault)throw new Error(storageFault);localStorage.setItem(storeKey,JSON.stringify(envelope));return true;}catch(error){storageFault=error.message||'Local saving is unavailable.';cloudStatus='Local save failed';return false;}}
function mutate(fn,message,{undo=true}={}){
  const previous=clone(state),next=clone(state);
  try{fn(next);next.updatedAt=Date.now();validateState(next);if(new TextEncoder().encode(JSON.stringify(next)).byteLength>650000)throw new Error('Your journal is too large for cloud sync. Export a backup and remove older notes.');}
  catch(error){toast(error.message);return false;}
  if(undo){history.push(previous);history=history.slice(-20);}state=next;envelope.pending=!!account;localGeneration++;ui.preparedText='';
  if(!persist())toast('Local saving failed. Export a backup from Connections now.');else if(message)toast(message);
  queueSync();render();return true;
}
function queueSync(){clearTimeout(syncTimer);if(!account||!cloudReady||cloudConflict||cloudWriting||!envelope.pending)return;cloudStatus=navigator.onLine?'Waiting to sync':'Offline · saved here';syncTimer=setTimeout(sync,1200);}
async function sync(){
  if(!account||!cloudReady||cloudWriting||cloudConflict||!envelope.pending||!navigator.onLine)return;
  const snapshot=clone(state),generation=localGeneration,uidAtStart=account.uid,keyAtStart=storeKey,authAtStart=authGeneration;cloudWriting=true;outgoingPayload=JSON.stringify(snapshot);cloudStatus='Syncing…';renderStatus();
  try{const revision=await cloud.save(snapshot,envelope.revision);if(account?.uid!==uidAtStart||storeKey!==keyAtStart||authAtStart!==authGeneration)return;envelope.revision=revision;envelope.pending=generation!==localGeneration;cloudError='';cloudStatus=envelope.pending?'Waiting to sync':'Synced to Firebase';persist();}
  catch(error){if(account?.uid!==uidAtStart||authAtStart!==authGeneration)return;cloudError=friendlyFirebaseError(error);cloudStatus=error.code==='rivet/conflict'?'Sync conflict':'Saved here · sync paused';if(error.code!=='rivet/conflict')toast(cloudError);}
  finally{if(account?.uid===uidAtStart&&authAtStart===authGeneration){cloudWriting=false;outgoingPayload=null;renderStatus();if(envelope.pending&&!cloudError)queueSync();}}
}
const cloud=new FirebaseStore({
  onUser(user){
    clearTimeout(syncTimer);persist();authGeneration++;outgoingPayload=null;account=user;cloudReady=false;cloudConflict=null;cloudError='';cloudWriting=false;history=[];ui.preparedText='';storeKey=storagePrefix+(user?'user:'+user.uid:'guest');storageFault='';
    envelope=readEnvelope(storeKey)||{state:defaultState(),revision:0,pending:false};state=envelope.state;localGeneration++;restoreDraft();cloudStatus=user?'Connecting to your sheet…':'Saved on this device';render();
  },
  onDocument(remote){
    cloudReady=true;
    try {
      if(!remote){if(envelope.pending)queueSync();else{cloudStatus='Signed in · no cloud sheet';render();}return;}
      if(!Number.isInteger(remote.revision)||remote.revision<1)throw new Error('Cloud sync metadata is invalid.');
      const remoteState=validateState(JSON.parse(remote.payload));
      if(remote.revision<=envelope.revision){if(!envelope.pending){cloudStatus='Synced to Firebase';renderStatus();}return;}
      // Ignore this device's own optimistic transaction echo; the save promise records its revision.
      if(cloudWriting&&remote.payload===outgoingPayload)return;
      if(envelope.pending){cloudConflict={state:remoteState,revision:remote.revision};cloudStatus='Sync conflict';render();return;}
      state=remoteState;envelope={state,revision:remote.revision,pending:false};history=[];ui.preparedText='';persist();restoreDraft();cloudStatus='Synced to Firebase';render();
    }catch(error){cloudStatus='Cloud data could not be read';cloudError=error.message;render();}
  },
  onError(error){cloudError=friendlyFirebaseError(error);cloudStatus='Saved here · sync paused';renderStatus();toast(cloudError);}
});
if(config)cloud.connect(config).catch(error=>{cloudError=friendlyFirebaseError(error);cloudStatus='Firebase needs attention';renderStatus();});
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4400);}
function renderStatus(){document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=storageFault?'Local save failed':cloudStatus);}
function formatDate(value){const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?value:d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});}
function time(value){return new Date(value).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});}
function header(title,subtitle,controls=''){return `<div class="page-heading"><div><div class="eyebrow">Dungeons & Dragons</div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${controls?`<div class="controls">${controls}</div>`:''}</div>`;}
function render(){
  const c=state.character;
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a href="#sheet" class="brand" aria-label="Rivet home"><img src="./icon.svg" alt=""><div><strong>Rivet</strong><small>Character sheet</small></div></a><div class="eyebrow nav-label">At the table</div><nav class="nav" aria-label="Main navigation">${views.map(([v,i,l])=>`<button data-action="view" data-view="${v}" class="${ui.view===v?'active':''}" ${ui.view===v?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}<button data-action="view" data-view="settings" class="${ui.view==='settings'?'active':''}">${icon('settings')}Connections</button></nav><div class="sidebar-bottom"><div class="campaign-mark"><div class="eyebrow">The current chapter</div><p class="serif">${esc(session().title)}</p><small>${esc(c.rules)}</small></div><button class="account-btn" data-action="account"><span class="account-icon">${account?esc((account.email||'A').slice(0,1).toUpperCase()):'R'}</span><span>${account?'Firebase account':'This device'}<small>${account?esc(account.email||'Connected'):'Connect to sync your sheet'}</small></span></button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><span>Character sheet</span><span class="crumb-arrow">/</span><span>${ui.view==='settings'?'Connections':views.find(v=>v[0]===ui.view)?.[2]}</span></div><div class="top-actions"><span class="status ${cloudError||storageFault?'warning':''}"><span class="status-dot"></span><span data-sync-status>${esc(storageFault?'Local save failed':cloudStatus)}</span></span><button class="account-mobile" data-action="account" aria-label="Account and connections">${icon('user')}</button></div></header><main id="main" class="main" tabindex="-1">${storageFault?`<div class="conflict-banner">${esc(storageFault)} ${action('recovery','Export recovery')}</div>`:''}${conflictView()}${({sheet:sheetView,spells:spellsView,journal:journalView,ask:askView,settings:settingsView}[ui.view])()}</main></div><nav class="bottom-nav" aria-label="Mobile navigation">${[['sheet','sheet','Sheet'],['spells','book','Spells'],['journal','journal','Journal'],['ask','spark','Ask']].map(([v,i,l])=>`<button data-action="view" data-view="${v}" class="${ui.view===v?'active':''}" aria-label="${l}" ${ui.view===v?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav></div>`;
}
function conflictView(){return cloudConflict?`<div class="conflict-banner"><strong>This sheet changed on another device.</strong><br>Both versions are available. Download a backup before choosing; your local version is also retained on this device.<div class="settings-actions">${action('export','Back up this device',{iconName:'download'})}${action('keep-local','Keep this device')}${action('keep-cloud','Use cloud version')}</div></div>`:'';}
function sheetView(){const c=state.character,p=proficiency(c.level),spellMod=mod(c.abilities[c.spellAbility]);return `
<div class="page-heading"><div class="character-name"><div class="crest">${icon('hammer')}</div><div><div class="eyebrow">Character sheet</div><h1>${esc(c.name)} <span>“${esc(c.nickname)}”</span></h1><div class="character-meta"><span>${esc(c.species)}</span><span class="dot-sep"></span><span>${esc(c.subclass)} ${esc(c.className)}</span><span class="level">LVL ${c.level}</span></div></div></div><div class="controls">${action('edit-character','Edit sheet',{iconName:'edit'})}${action('rest','Rest',{iconName:'moon'})}${action('undo','',{type:'text',iconName:'undo',extra:'aria-label="Undo last change"',disabled:!history.length})}</div></div>
${!state.reviewed?`<div class="notice"><span>Rivet is an editable starting point. Confirm HP, armour and resources before play.</span>${action('edit-character','Review sheet')}</div>`:''}
<div class="dashboard"><div class="sheet-column"><div class="combat-grid"><section class="card hp-card" aria-label="Hit points"><div class="card-header"><span class="eyebrow">Hit points</span>${icon('heart')}</div><div class="hp-values"><span class="current">${c.hp}</span><span class="slash">/</span><span class="max">${c.maxHp}</span></div><div class="hp-caption">${c.hp===0?'At zero · check death saves':c.hp===c.maxHp?'Ready for what comes next':c.hp<=c.maxHp/2?'Bloodied · half HP or less':'Still standing strong'}</div><div class="hp-bar" role="progressbar" aria-label="Hit points" aria-valuenow="${c.hp}" aria-valuemin="0" aria-valuemax="${c.maxHp}"><span style="width:${c.hp/c.maxHp*100}%"></span></div><div class="hp-controls"><input aria-label="HP adjustment amount" id="hp-amount" type="number" inputmode="numeric" min="1" max="9999" value="${ui.hpAmount}"><button class="damage" data-action="hp" data-type="damage">− Damage</button><button data-action="hp" data-type="heal">+ Heal</button></div><div class="hp-footer"><span>Temporary HP <strong>${c.tempHp}</strong></span><button data-action="temp-hp">Add temp HP</button></div>${c.hp===0?deathView():''}</section><div class="stats-grid"><div class="card stat">${icon('shield')}<strong>${c.ac}</strong><label>Armour class</label></div><div class="card stat">${icon('bolt')}<strong>${bonus(c.initiativeBonus)}</strong><label>Initiative</label></div><div class="card stat">${icon('boot')}<strong>${c.speed}<span style="font-size:13px"> ft</span></strong><label>Speed</label></div><div class="card stat">${icon('target')}<strong>${bonus(p)}</strong><label>Proficiency</label></div></div></div>
<section class="section-gap"><div class="section-title"><h2>Abilities</h2><span>Score / modifier</span></div><div class="abilities">${ABILITIES.map(a=>`<div class="ability" aria-label="${ABILITY_NAMES[a]}, score ${c.abilities[a]}, modifier ${bonus(mod(c.abilities[a]))}"><span class="eyebrow">${a.toUpperCase()}</span><span class="modifier">${bonus(mod(c.abilities[a]))}</span><span class="score">${c.abilities[a]}</span></div>`).join('')}</div></section>
<section class="card card-pad section-gap"><div class="card-header"><h2>In the moment</h2>${action('conditions','Manage',{type:'text small',iconName:'plus'})}</div><div class="condition-row"><div class="conditions">${c.conditions.length?c.conditions.map(s=>`<span class="chip rust">${esc(s)}</span>`).join(''):'<span class="chip">No conditions</span>'}${c.exhaustion?`<span class="chip rust">Exhaustion ${c.exhaustion}</span>`:''}</div><button class="inspiration ${c.inspiration?'on':''}" data-action="inspiration" aria-pressed="${c.inspiration}">${icon('star')}Inspiration</button></div>${c.exhaustion?`<p class="help">Apply the 2024 exhaustion penalty of −${2*c.exhaustion} to D20 Tests and reduce Speed by ${5*c.exhaustion} ft. Apply these adjustments at the table.</p>`:''}${concentrationView()}</section>
<section class="card card-pad section-gap"><div class="card-header"><h2>Skills & senses</h2><span class="eyebrow">${Object.values(c.skills).filter(Boolean).length} proficient</span></div><div class="skill-list">${Object.entries(SKILLS).map(([name,a])=>{const b=mod(c.abilities[a])+(c.skills[name]||0)*p;return `<div class="skill-row"><span class="skill-dot ${c.skills[name]?'on':''} ${c.skills[name]===2?'expert':''}"></span><span class="skill-name">${esc(name)}</span><span class="skill-ability">${a.toUpperCase()}</span><span class="skill-bonus">${bonus(b)}</span></div>`;}).join('')}</div><div class="passives"><span>Passive Perception <strong>${10+mod(c.abilities.wis)+(c.skills.Perception||0)*p}</strong></span><span>Passive Insight <strong>${10+mod(c.abilities.wis)+(c.skills.Insight||0)*p}</strong></span></div></section>
<section class="card card-pad section-gap"><div class="card-header"><h2>Saving throws</h2><span class="muted" style="font-size:10px">Saving throw bonuses</span></div><div class="saving-list">${ABILITIES.map(a=>{const b=mod(c.abilities[a])+(c.saves.includes(a)?p:0);return `<div class="save-row"><span class="skill-dot ${c.saves.includes(a)?'on':''}"></span>${ABILITY_NAMES[a]}<span class="skill-bonus">${bonus(b)}</span></div>`;}).join('')}</div></section>
<section class="card card-pad section-gap"><div class="card-header"><h2>Equipment & coin</h2>${action('equipment','Edit',{type:'text small',iconName:'edit'})}</div><div class="equipment-text">${esc(c.equipment)||'Your pack is empty.'}</div><div class="passives"><span>Gold pieces</span><strong>${c.gold.toLocaleString()} gp</strong></div></section>
</div><aside class="aside-column">${slotsCard()}<section class="card card-pad"><div class="card-header"><h2>Class resources</h2>${action('resources','Edit',{type:'text small',iconName:'edit'})}</div>${c.resources.map(r=>`<div class="resource"><div class="resource-info"><span>${esc(r.name)}</span><span class="resource-count">${r.max-r.used}/${r.max}</span></div><div class="pips">${Array.from({length:r.max},(_,i)=>`<button class="pip ${i>=r.max-r.used?'spent':''}" data-action="resource-pip" data-id="${esc(r.id)}" data-index="${i}" aria-label="${esc(r.name)}, use ${i+1} of ${r.max}, ${i<r.max-r.used?'available':'spent'}">${icon('spark')}</button>`).join('')}</div></div>`).join('')}<div class="passives"><span>Hit Dice</span><strong>${c.hitDice}/${c.maxHitDice} d${c.hitDie}</strong></div></section>
${sessionCard()}<section class="card card-pad"><div class="card-header"><h2>Table log</h2>${icon('scroll')}</div><div class="activity">${state.log.length?state.log.slice(0,5).map(l=>`<div class="activity-item"><span class="activity-dot"></span><div>${esc(l.text)}<small>${time(l.at)}</small></div></div>`).join(''):'<p class="quiet-empty">Your HP changes, spell use and rests appear here.</p>'}</div></section><section class="card card-pad"><div class="card-header"><h2>Traits & story</h2>${action('features','Edit',{type:'text small',iconName:'edit'})}</div><p class="equipment-text">${esc(c.features)}</p><p class="session-note">${esc(c.backstory)}</p></section></aside></div>`;}
function deathView(){const d=state.character.death;return `<div class="death-panel"><strong>Death saves</strong>${['success','failure'].map(type=>`<div><span>${type==='success'?'Successes':'Failures'}</span><span>${[0,1,2].map(i=>`<button class="${type==='failure'?'fail ':''}${i<d[type]?'marked':''}" data-action="death" data-type="${type}" data-index="${i}" aria-label="${type} ${i+1}" aria-pressed="${i<d[type]}">${i<d[type]?'●':'○'}</button>`).join(' ')}</span></div>`).join('')}<p>${d.failure===3?'Three failures. Confirm the outcome with your DM.':d.success===3?'Three successes: stable, still at zero HP.':'Track saves manually. Damage at zero and instant death need DM review.'}</p></div>`;}
function concentrationView(){const c=state.character;return `<div class="concentration ${c.concentration?'active':''}">${icon('spark')}<span>${c.concentration?`Concentrating · <strong>${esc(c.concentration)}</strong>`:'Not concentrating'}</span>${c.concentration?`<button data-action="end-concentration" aria-label="End concentration">${icon('close')}</button>`:''}</div>`;}
function slotsCard(){const c=state.character,p=proficiency(c.level),m=mod(c.abilities[c.spellAbility]);return `<section class="card card-pad slots-card"><div class="card-header"><h2>Spellcasting</h2>${action('view','',{type:'text small',iconName:'arrow',extra:'data-view="spells" aria-label="Open spellbook"'})}</div><div class="spell-summary"><div><strong>${8+p+m}</strong><small>Save DC</small></div><div><strong>${bonus(p+m)}</strong><small>Spell attack</small></div><div><strong>${c.spellAbility.toUpperCase()}</strong><small>Ability</small></div></div><div class="slot-rows">${c.slots.filter(s=>s.max>0).map(s=>`<div class="slots-row"><span class="slot-label">Level ${s.level}<br><small class="resource-count">${s.max-s.used} / ${s.max}</small></span><div class="pips">${Array.from({length:s.max},(_,i)=>`<button class="pip ${i>=s.max-s.used?'spent':''}" data-action="slot-pip" data-level="${s.level}" data-index="${i}" aria-label="Level ${s.level} slot ${i+1}, ${i<s.max-s.used?'available':'spent'}">${icon('spark')}</button>`).join('')}</div></div>`).join('')||'<p class="quiet-empty">Add spell slots in Edit sheet.</p>'}</div><p class="help">Filled slots are available. Tap to spend or restore.</p></section>`;}
function sessionCard(){const s=session();return `<section class="card card-pad session-card"><div class="eyebrow">Current session</div><h2 class="session-title">${esc(s.title)}</h2><div class="date">${formatDate(s.date)} · ${s.notes.length} notes</div>${s.notes.length?`<p class="session-note">${esc(s.notes[s.notes.length-1].text)}</p>`:'<p class="quiet-empty">A new chapter awaits.</p>'}${action('view','Open session journal',{iconName:'journal',extra:'data-view="journal"'})}</section>`;}
function spellsView(){const c=state.character,spells=c.spells.filter(s=>(ui.spellLevel==='all'||s.level===Number(ui.spellLevel))&&(!ui.preparedOnly||s.prepared)&&s.name.toLowerCase().includes(ui.spellSearch.toLowerCase()));return `${header('Your spellbook','Prepared spells and remaining slots.',action('new-spell','Add spell',{type:'primary',iconName:'plus'}))}<div class="spellbook-layout"><div><div class="filter-bar"><label class="search">${icon('search')}<input id="spell-search" aria-label="Search spells" placeholder="Find a spell…" value="${esc(ui.spellSearch)}"></label><select id="spell-level" aria-label="Filter spell level"><option value="all">All levels</option>${Array.from({length:10},(_,i)=>`<option value="${i}" ${ui.spellLevel===String(i)?'selected':''}>${i===0?'Cantrips':'Level '+i}</option>`).join('')}</select><label class="check-label"><input id="prepared-only" type="checkbox" ${ui.preparedOnly?'checked':''}>Prepared only</label></div><div id="spell-results">${spellResults(spells)}</div></div><aside class="aside-column">${slotsCard()}<section class="card card-pad"><h2 style="font-size:22px">Keep your focus</h2>${concentrationView()}<p class="help">Casting a concentration spell replaces your current concentration. Casting records a spell slot. Resolve its effects at the table.</p></section></aside></div>`;}
function spellResults(spells){if(!spells.length)return '<div class="empty-state card"><h2>No spells found</h2><p>Try another name or add your own spell.</p></div>';return [...new Set(spells.map(s=>s.level))].sort((a,b)=>a-b).map(level=>`<h2 class="spell-level-title">${level===0?'Cantrips':'Level '+level}<span>${level===0?'At will':'Spells'}</span></h2><div>${spells.filter(s=>s.level===level).map(s=>`<div class="spell-row ${s.prepared?'':'unprepared'}"><div class="spell-glyph">${icon(s.level===0?'sun':'spark')}</div><button class="spell-main" data-action="spell-detail" data-id="${esc(s.id)}"><strong>${esc(s.name)}${s.concentration?'<span class="c-mark" title="Concentration">C</span>':''}</strong><small>${esc(s.time)} · ${esc(s.range)}${s.prepared?'':' · Not prepared'}</small></button>${action('spell-detail','Cast',{type:'soft small',extra:`data-id="${esc(s.id)}" aria-label="Cast ${esc(s.name)}"`,disabled:!s.prepared})}</div>`).join('')}</div>`).join('');}
function journalView(){const s=session();return `${header('Session journal','Session notes and campaign details.',action('new-session','New session',{type:'primary',iconName:'plus'}))}<div class="journal-layout"><aside><div class="session-list">${[...state.sessions].reverse().map(x=>`<button class="${s.id===x.id?'active':''}" data-action="select-session" data-id="${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${formatDate(x.date)}<span>${x.notes.length} notes</span></small></button>`).join('')}</div><p class="help desktop-only" style="padding:10px">Only this session’s included notes and notes marked “Carry forward” are shared with ChatGPT.</p></aside><div><div class="journal-top"><div><div class="eyebrow muted">Active session</div><h2>${esc(s.title)}</h2><small>${formatDate(s.date)}</small></div>${action('edit-session','',{type:'text',iconName:'edit',extra:'aria-label="Edit session"'})}</div><form id="note-form" class="composer"><textarea id="note-draft" maxlength="10000" aria-label="Session note" placeholder="A name to remember. A clue. A questionable decision…" required>${esc(ui.noteDraft)}</textarea><div class="composer-footer"><select id="note-tag" aria-label="Note category">${['Story','NPC','Loot','Quest','Ruling'].map(t=>`<option ${ui.noteTag===t?'selected':''}>${t}</option>`).join('')}</select><button type="submit" class="btn primary">${icon('plus')}Save note</button></div></form><div class="journal-meta"><span>${s.notes.length} notes</span><span>·</span><span>${s.notes.filter(n=>n.include).length} included for ChatGPT</span></div>${s.notes.length?[...s.notes].reverse().map(n=>`<article class="card note"><div class="note-top"><span class="chip ${n.tag==='Ruling'?'gold':n.tag==='NPC'?'rust':''}">${esc(n.tag)}</span>${n.carry?'<span class="chip">Carried forward</span>':''}<span class="time">${time(n.createdAt)}</span></div><p>${esc(n.text)}</p><div class="note-footer"><div style="display:flex;gap:12px;flex-wrap:wrap"><label class="check-label"><input type="checkbox" data-note-toggle="include" data-id="${esc(n.id)}" ${n.include?'checked':''}>Include for ChatGPT</label><label class="check-label"><input type="checkbox" data-note-toggle="carry" data-id="${esc(n.id)}" ${n.carry?'checked':''}>Carry forward</label></div><div class="note-actions">${action('edit-note','',{type:'text',iconName:'edit',extra:`data-id="${esc(n.id)}" aria-label="Edit note"`})}${action('delete-note','',{type:'text',iconName:'trash',extra:`data-id="${esc(n.id)}" aria-label="Delete note"`})}</div></div></article>`).join(''):'<div class="card empty-state"><h2>Every adventure starts somewhere.</h2><p>Add the first note for this session.</p></div>'}</div></div>`;}
function askView(){const notes=contextNotes(state),s=session(),qs=state.questions.filter(q=>q.sessionId===s.id);return `${header('A second pair of eyes','Your character and session notes, ready for ChatGPT.')}<div class="ask-layout"><div><section class="card ask-intro"><div class="ask-symbol">${icon('spark')}</div><h2>A ruling, a reminder,<br>or your next move.</h2><p>Prepare a question with your current sheet and selected notes. Copy it, then paste it into ChatGPT using your own account.</p><div class="suggestions">${['What can I do this turn?','How does concentration work?','Recap this session.'].map(q=>`<button data-action="suggest-question" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="ask-form" class="ask-composer"><textarea id="ask-draft" aria-label="Question for ChatGPT" maxlength="4000" placeholder="Can I cast Healing Word and attack on the same turn?" required>${esc(ui.question)}</textarea><div class="composer-footer"><span class="muted" style="font-size:10px">${icon('lock')} Nothing shared until you paste</span><button type="submit" class="btn primary">Prepare question ${icon('arrow')}</button></div></form><p class="ask-footnote">ChatGPT opens separately. Choose Fast / Instant there if your account offers it. Concise answers below controls the prompt, not the model speed.</p></section>${ui.preparedText?`<section class="card prepared"><h3>Your question is ready.</h3><p>1. Copy the prompt. 2. Open ChatGPT, sign in if needed, and paste it.</p><div class="prepared-actions">${action('copy-context','1 · Copy context',{type:'primary',iconName:'copy'})}<a class="btn" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">2 · Open ChatGPT ${icon('external')}</a></div><details class="context-preview"><summary>Review exactly what you’re sharing · ${ui.preparedText.length.toLocaleString()} characters</summary><pre>${esc(ui.preparedText)}</pre></details></section>`:''}</div><aside class="aside-column"><section class="card card-pad context-card"><div class="card-header"><h2>In the conversation</h2>${icon('book')}</div><div class="context-list"><div>${icon('shield')}<span><strong>${esc(state.character.nickname||state.character.name)}</strong><small>Live stats, equipment & spells</small></span></div><div>${icon('journal')}<span><strong>${esc(s.title)}</strong><small>${notes.length} selected notes</small></span></div></div><div class="toggle-row"><span>Include session notes</span><label class="toggle"><input id="include-notes" type="checkbox" aria-label="Include session notes" ${ui.includeNotes?'checked':''}><span></span></label></div><div class="toggle-row"><span>Concise answers</span><label class="toggle"><input id="concise" type="checkbox" aria-label="Concise answers" ${ui.concise?'checked':''}><span></span></label></div></section><section class="card card-pad history-card"><div class="card-header"><h2>Recent questions</h2></div>${qs.length?qs.slice(0,5).map(q=>`<button class="history-question" data-action="suggest-question" data-question="${esc(q.text)}">${esc(q.text)}</button>`).join(''):'<p class="quiet-empty">Your prepared questions for this session will appear here.</p>'}</section><section class="card card-pad"><h2 style="font-size:21px;margin-bottom:12px">About the connection</h2><p class="quiet-empty">This version hands off to ChatGPT. Embedded sign-in and replies need an approved integration; there is no AI request or model connection running inside the sheet.</p>${action('view','Connection details',{type:'text small',extra:'data-view="settings"'})}</section></aside></div>`;}
function settingsView(){return `${header('Connections & safekeeping','Your sheet should be there when the adventure calls.')}<div class="settings-grid"><section class="card card-pad"><h2>Your saved sheet</h2><div class="settings-list"><div><span>This browser</span><span>${storageFault?'Save unavailable':'Local autosave enabled'}</span></div><div><span>Firebase</span><span>${account?'Signed in':config?'Configured · sign in':'Not configured'}</span></div><div><span>Sync status</span><span>${esc(cloudStatus)}</span></div></div>${cloudError?`<p class="error-text">${esc(cloudError)}</p>`:''}<p style="margin-top:16px">Export a backup before changing devices or clearing browser data. Local sheets stay on this browser until Firebase is connected.</p><div class="settings-actions">${action('account',account?'Manage account':'Connect Firebase',{type:'primary',iconName:'cloud'})}${action('export','Export backup',{iconName:'download'})}${action('import','Import backup',{iconName:'upload'})}</div></section><section class="card card-pad"><h2>ChatGPT</h2><span class="chip gold" style="margin-bottom:15px">Context handoff available</span><p>Copy your current sheet and selected session notes into ChatGPT. Sign in there with your existing account; select the response mode there.</p><p>Embedded ChatGPT sign-in and AI replies are not connected. Website sign-in is currently a limited partner trial. The open-source plan-usage flow requires a local callback listener, which a mobile-only browser app cannot run.</p><a class="btn" href="https://developers.openai.com/siwc/website" target="_blank" rel="noopener noreferrer">Official sign-in documentation ${icon('external')}</a></section><section class="card card-pad"><h2>Built for your phone</h2><p>On iPhone, open the sheet in Safari, tap Share, then Add to Home Screen. On Android, use your browser’s Install app or Add to Home screen option.</p><p>The character sheet works offline after the first load. Google sign-in, cloud sync and ChatGPT need a connection. Exported backups include the complete sheet and session notes.</p>${action('install','Installation options',{iconName:'plus'})}</section><section class="card card-pad"><h2>Firebase Spark only</h2><p>This app uses Firebase Authentication, Cloud Firestore and static Hosting. It includes no Cloud Functions, paid AI calls, Storage or App Hosting. Keep the project on the Spark plan.</p><p>Changes are saved locally and cloud writes are debounced. If quotas are reached, cloud operations pause; local play continues. Simultaneous device edits require you to choose a version.</p><div class="settings-actions">${action('firebase-config','Firebase configuration',{iconName:'settings'})}<a class="btn text" href="https://firebase.google.com/docs/projects/billing/firebase-pricing-plans" target="_blank" rel="noopener noreferrer">Plan details ${icon('external')}</a></div></section><section class="card card-pad"><h2>Rules & starting values</h2><p>The starter sheet uses the 2024 rules with Lee’s approved legacy Forge Domain. Confirm all provisional values before play. This is a table companion; your DM resolves rulings and special cases.</p><p>Edit your stats and slots manually. Conditions and class-specific effects are tracked for reference; resolve their effects at the table.</p>${action('edit-character','Review character',{iconName:'edit'})}</section><section class="card card-pad"><h2>Your data</h2><p>Firebase data lives under your authenticated user ID. Signing out returns to this device’s separate guest sheet. Account data remains locally cached; use the option below on shared devices.</p><div class="settings-actions">${action('clear-cache','Clear saved data on this device',{iconName:'trash'})}${action('print','Print sheet',{iconName:'sheet'})}</div><p class="help" style="margin-top:18px">Rivet is an independent fan tool and is not affiliated with Wizards of the Coast or OpenAI. <a href="./LICENSES.txt" target="_blank">Rules attribution</a>.</p></section></div>`;}
function openModal(title,body){modalReturnFocus=document.activeElement;const d=$('#modal');d.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2>${action('close','',{type:'icon-only text',iconName:'close',extra:'aria-label="Close dialog"'})}</div><div class="modal-body">${body}<div id="modal-error" class="error-text" role="alert"></div></div>`;if(!d.open)d.showModal();const first=d.querySelector('input:not([type=checkbox]),textarea,select');if(first&&innerWidth>700)first.focus();}
function closeModal(){$('#modal').close();if(modalReturnFocus?.isConnected)modalReturnFocus.focus();}
function modalError(error){const el=$('#modal-error');if(el)el.textContent=friendlyFirebaseError(error);else toast(friendlyFirebaseError(error));}
const field=(name,label,value,type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'inputmode="numeric"':''} ${extra}></label>`;
const textarea=(name,label,value,extra='')=>`<label class="field">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const footer=(text='Save changes',extra='')=>`<div class="modal-actions">${extra}${action('close','Cancel')}<button type="submit" class="btn primary">${text}</button></div>`;
function editCharacter(){const c=state.character;openModal('Make this character yours',`<form id="character-form"><p>The starting values are provisional. Review these with your DM before your first session.</p><div class="form-grid">${field('name','Name',c.name,'text','required maxlength="150"')}${field('nickname','Nickname',c.nickname,'text','maxlength="150"')}${field('species','Species',c.species,'text','maxlength="150"')}${field('className','Class',c.className,'text','maxlength="150"')}${field('subclass','Subclass',c.subclass,'text','maxlength="150"')}${field('level','Level',c.level,'number','min="1" max="20" required')}${field('background','Background',c.background,'text','maxlength="150"')}${field('alignment','Alignment',c.alignment,'text','maxlength="150"')}<label class="field wide">Rules edition / house rules<input name="rules" value="${esc(c.rules)}" maxlength="150"></label></div><h3 class="form-section">At the table</h3><div class="form-grid three">${field('maxHp','Max HP',c.maxHp,'number','min="1" max="9999" required')}${field('hp','Current HP',c.hp,'number','min="0" max="9999" required')}${field('tempHp','Temporary HP',c.tempHp,'number','min="0" max="9999" required')}${field('ac','Armour class',c.ac,'number','min="0" max="99" required')}${field('speed','Speed (ft)',c.speed,'number','min="0" max="999" required')}${field('initiativeBonus','Initiative bonus',c.initiativeBonus,'number','min="-20" max="50" required')}</div><h3 class="form-section">Ability scores</h3><div class="form-grid six">${ABILITIES.map(a=>field(a,a.toUpperCase(),c.abilities[a],'number','min="1" max="30" required')).join('')}</div><p class="help">Proficiency, skill bonuses and spell DC update automatically. Initiative, HP and slot counts remain manual so feats and house rules are respected.</p><h3 class="form-section">Saving throw proficiencies</h3><div class="checkbox-grid">${ABILITIES.map(a=>`<label><input type="checkbox" name="save-${a}" ${c.saves.includes(a)?'checked':''}>${ABILITY_NAMES[a]}</label>`).join('')}</div><h3 class="form-section">Skill proficiencies</h3><div class="form-grid">${Object.keys(SKILLS).map(name=>`<label class="field">${esc(name)}<select name="skill-${esc(name)}">${[[0,'Untrained'],[1,'Proficient'],[2,'Expertise']].map(([v,l])=>`<option value="${v}" ${(c.skills[name]||0)===v?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div><h3 class="form-section">Rest & spellcasting</h3><div class="form-grid three"><label class="field">Hit Die<select name="hitDie">${[6,8,10,12].map(n=>`<option value="${n}" ${c.hitDie===n?'selected':''}>d${n}</option>`).join('')}</select></label>${field('maxHitDice','Max Hit Dice',c.maxHitDice,'number','min="1" max="20" required')}${field('hitDice','Remaining Hit Dice',c.hitDice,'number','min="0" max="20" required')}<label class="field">Spell ability<select name="spellAbility">${ABILITIES.map(a=>`<option value="${a}" ${c.spellAbility===a?'selected':''}>${a.toUpperCase()}</option>`).join('')}</select></label></div><h3 class="form-section">Spell slots</h3><p class="help">Enter maximum and spent slots. These do not change automatically when you change level or class.</p><div class="form-grid">${Array.from({length:9},(_,i)=>{const slot=c.slots.find(s=>s.level===i+1)||{max:0,used:0};return `${field('slot-max-'+(i+1),'Level '+(i+1)+' · max',slot.max,'number','min="0" max="20" required')}${field('slot-used-'+(i+1),'Level '+(i+1)+' · spent',slot.used,'number','min="0" max="20" required')}`;}).join('')}</div><label class="check-label" style="margin-top:20px;font-size:12px"><input type="checkbox" name="reviewed" ${state.reviewed?'checked':''}>I have reviewed the starting values.</label>${footer('Save character')}</form>`);}
function editSimple(kind){const c=state.character;if(kind==='equipment')openModal('Equipment & coin',`<form id="equipment-form">${textarea('equipment','Equipment and quantities',c.equipment,'maxlength="12000" style="min-height:180px"')}<div style="margin-top:16px">${field('gold','Gold pieces',c.gold,'number','min="0" max="9999999" required')}</div>${footer()}</form>`);else openModal('Traits & story',`<form id="features-form">${textarea('features','Features, feats & house rules',c.features,'maxlength="12000" style="min-height:160px"')}<div style="margin-top:16px">${textarea('backstory','Backstory',c.backstory,'maxlength="12000"')}</div>${footer()}</form>`);}
function editResources(){const c=state.character;openModal('Class resources',`<form id="resources-form"><p>Configure limited-use features. Tap the pips on your sheet to spend or restore uses.</p>${c.resources.map((r,i)=>`<div class="form-grid" style="padding:17px 0;border-bottom:1px solid var(--line)">${field('r-name-'+i,'Resource name',r.name,'text','maxlength="150" required')}${field('r-max-'+i,'Maximum uses',r.max,'number','min="1" max="99" required')}${field('r-used-'+i,'Spent uses',r.used,'number','min="0" max="99" required')}<label class="field">Full reset<select name="r-reset-${i}">${['long','short','manual'].map(t=>`<option value="${t}" ${r.reset===t?'selected':''}>${t==='manual'?'Manual':t+' rest'}</option>`).join('')}</select></label>${field('r-short-'+i,'Uses recovered on short rest',r.shortRecovery,'number','min="0" max="99" required')}<label class="check-label"><input type="checkbox" name="r-delete-${i}">Remove resource</label></div>`).join('')}<h3 class="form-section">Add a resource</h3><div class="form-grid">${field('new-name','Name (optional)','','text','maxlength="150"')}${field('new-max','Maximum uses',1,'number','min="1" max="99"')}</div>${footer()}</form>`);}
function editConditions(){const c=state.character;openModal('Conditions & focus',`<form id="conditions-form"><div class="checkbox-grid">${CONDITIONS.map(x=>`<label><input type="checkbox" name="condition-${x}" ${c.conditions.includes(x)?'checked':''}>${x}</label>`).join('')}</div><div class="form-grid" style="margin-top:20px">${field('exhaustion','Exhaustion level',c.exhaustion,'number','min="0" max="6" required')}${field('concentration','Concentrating on',c.concentration,'text','maxlength="150"')}</div><p class="help">Conditions and exhaustion are tracked here. Apply their roll and movement effects with your DM. Incapacitation-related conditions end concentration.</p>${footer()}</form>`);}
function restDialog(){const c=state.character;openModal('A moment to recover',`<p>Confirm the rest is complete with your DM before applying its benefits.</p><form id="short-rest-form"><h3 class="form-section">Short rest</h3><p>Record the Hit Dice you spent and total healing from your physical dice, including Constitution (${bonus(mod(c.abilities.con))}). ${c.hitDice} of ${c.maxHitDice} d${c.hitDie} available.</p><div class="form-grid">${field('dice','Hit Dice to spend',c.hitDice?1:0,'number',`min="0" max="${c.hitDice}" required`)}${field('healing','Total healing',0,'number','min="0" max="9999" required')}</div><div class="modal-actions"><button type="submit" class="btn soft">Apply short rest</button></div><p class="help">Configured short-rest resources also recover. No spell slots are restored automatically.</p></form><h3 class="form-section">Long rest</h3><p>Restore HP, all Hit Dice, spell slots and eligible class resources. Clear temporary HP, concentration and death saves; reduce exhaustion by one. Other conditions remain for manual review.</p>${action('long-rest','Apply completed long rest',{type:'primary full',iconName:'moon',disabled:c.hp===0})}${c.hp===0?'<p class="help">You need at least 1 HP to begin a long rest.</p>':''}`);}
function spellDetail(id){const c=state.character,s=c.spells.find(s=>s.id===id);if(!s)return;const available=c.slots.filter(x=>x.level>=s.level&&x.max>x.used);openModal(esc(s.name),`<span class="chip">${s.level===0?'Cantrip':'Level '+s.level}</span>${s.concentration?' <span class="chip gold">Concentration</span>':''}<div class="spell-detail"><div>Casting time<strong>${esc(s.time)}</strong></div><div>Range<strong>${esc(s.range)}</strong></div><div>Preparation<strong>${s.prepared?'Prepared':'Not prepared'}</strong></div></div><p style="white-space:pre-wrap">${esc(s.notes)||'No spell notes yet. Add your table’s reference.'}</p>${s.concentration&&c.concentration?`<p class="notice">Casting this ends concentration on ${esc(c.concentration)}.</p>`:''}<form id="cast-form" data-id="${esc(id)}">${s.level>0?`<label class="field cast-select">Cast with a spell slot<select name="castLevel" ${!available.length?'disabled':''}>${available.length?available.map(x=>`<option value="${x.level}">Level ${x.level} · ${x.max-x.used} remaining</option>`).join(''):'<option>No available slots</option>'}</select></label>`:''}<div class="modal-actions">${action('edit-spell','Edit',{iconName:'edit',extra:`data-id="${esc(id)}"`})}<button type="submit" class="btn primary" ${!s.prepared||(s.level>0&&!available.length)?'disabled':''}>${icon('spark')}${s.level===0?'Cast cantrip':'Cast & spend slot'}</button></div></form><p class="help">Verify components, range and your turn’s spellcasting limits. Casting records the use only; resolve attacks, damage and effects at the table.</p>`);}
function editSpell(id){const s=state.character.spells.find(x=>x.id===id)||{id:'',name:'',level:1,time:'Action',range:'',notes:'',concentration:false,prepared:true};openModal(s.id?'Edit spell':'Add a spell',`<form id="spell-form" data-id="${esc(s.id)}"><div class="form-grid">${field('name','Spell name',s.name,'text','required maxlength="150"')}${field('level','Level (0 = cantrip)',s.level,'number','min="0" max="9" required')}${field('time','Casting time',s.time,'text','maxlength="100"')}${field('range','Range',s.range,'text','maxlength="100"')}</div><div style="margin-top:16px">${textarea('notes','Your spell reference',s.notes,'maxlength="5000"')}</div><div class="checkbox-grid" style="margin-top:15px"><label><input type="checkbox" name="concentration" ${s.concentration?'checked':''}>Concentration</label><label><input type="checkbox" name="prepared" ${s.prepared?'checked':''}>Prepared</label></div>${footer('Save spell',s.id?action('delete-spell','Delete',{type:'danger',extra:`data-id="${esc(s.id)}"`}):'')}</form>`);}
function sessionDialog(edit=false){const s=edit?session():{title:'',date:new Date().toLocaleDateString('en-CA')};openModal(edit?'Edit session':'Begin a new chapter',`<form id="session-form" data-edit="${edit}"><div class="form-grid">${field('title','Session title',s.title,'text','required maxlength="150" placeholder="A name for this chapter"')}${field('date','Session date',s.date,'date','required')}</div><p class="help">Each session keeps its own journal. Carried-forward notes remain available as context in later sessions.</p>${footer(edit?'Save session':'Create session')}</form>`);}
function noteDialog(id){const note=session().notes.find(n=>n.id===id);if(!note)return;openModal('Edit session note',`<form id="edit-note-form" data-id="${esc(id)}">${textarea('text','Note',note.text,'required maxlength="10000" style="min-height:200px"')}<label class="field" style="margin-top:15px">Category<select name="tag">${['Story','NPC','Loot','Quest','Ruling'].map(t=>`<option ${note.tag===t?'selected':''}>${t}</option>`).join('')}</select></label>${footer()}</form>`);}
function accountDialog(){
  if(!config){openModal('Keep your adventure in sync',`<p>Your sheet is saving on this device. To sync across your phone and computer, connect your own Firebase project on the free Spark plan.</p><div class="settings-list"><div><span>Authentication</span><span>Email or Google sign-in</span></div><div><span>Character & notes</span><span>Private Cloud Firestore records</span></div><div><span>Billing</span><span>Spark · no billing account</span></div></div><div class="modal-actions">${action('close','Keep playing locally')}${action('firebase-config','Set up Firebase',{type:'primary',iconName:'cloud'})}</div><p class="help">ChatGPT is separate: use Ask ChatGPT to prepare and copy your session context.</p>`);return;}
  if(!cloud.ready){openModal('Firebase connection',`<p>${esc(cloudError||'Connecting to Firebase…')}</p>${action('firebase-config','Review configuration')}`);return;}
  if(account){openModal('Your Firebase account',`<p>Signed in as <strong>${esc(account.email||account.uid)}</strong>.</p><p>${esc(cloudStatus)}</p>${cloudError?`<p class="error-text">${esc(cloudError)}</p>`:''}<div class="settings-actions">${action('sync-now','Sync this sheet',{type:'primary',iconName:'cloud'})}${action('bring-guest','Use this device’s guest sheet',{iconName:'sheet'})}${action('sign-out','Sign out')}</div><p class="help">Using the guest sheet replaces this account’s sheet after confirmation. Signing out keeps each account’s local data separate.</p>`);return;}
  openModal('Sign in to save your adventure',`<p>Your Firebase account syncs your character and session notes. It is separate from your ChatGPT account.</p>${action('google-auth','Continue with Google',{type:'full',iconName:'user'})}<div class="form-section">Or use your email</div><form id="auth-form"><div class="form-grid"><label class="field wide">Email<input name="email" type="email" autocomplete="email" required></label><label class="field wide">Password<input name="password" type="password" autocomplete="current-password" minlength="6" required></label></div><label class="check-label" style="margin-top:16px;font-size:12px"><input type="checkbox" name="create">Create a new account</label><div class="modal-actions">${action('reset-password','Reset password',{type:'text'})}<button class="btn primary" type="submit">Continue</button></div></form>`);
}
function configDialog(){const current=config?JSON.stringify(config,null,2):'{\n  "apiKey": "",\n  "authDomain": "your-project.firebaseapp.com",\n  "projectId": "your-project",\n  "appId": ""\n}';openModal('Connect your Firebase project',`<form id="config-form"><p>Use a Spark project with Email/Password or Google authentication enabled and the included Firestore rules deployed.</p><p>Paste the public web-app config from Firebase Console → Project settings → Your apps. Add <strong>${esc(location.hostname)}</strong> to Authentication → Authorized domains.</p>${textarea('config','Firebase web configuration (JSON)',current,'required style="min-height:210px;font-family:ui-monospace,monospace;font-size:12px"')}<p class="help">Only public Firebase config belongs here. Never paste a service-account private key, OAuth client secret or OpenAI API key. Saving reloads the page; your local sheet is retained.</p>${footer('Save & connect')}</form>`);}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportState(){download(`rivet-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));toast('Backup downloaded. Keep it somewhere safe.');}
function confirmDialog(title,text,actionName,buttonLabel,extra=''){openModal(title,`<p>${text}</p><div class="modal-actions">${action('close','Cancel')}${action(actionName,buttonLabel,{type:'primary',extra})}</div>`);}
let importedState=null;
let installPrompt=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
function navigate(view){if(!['sheet','spells','journal','ask','settings'].includes(view))return;saveDraft();ui.view=view;location.hash=view;render();window.scrollTo({top:0});}
async function clickAction(button){const a=button.dataset.action,id=button.dataset.id,c=state.character;
  switch(a){
    case 'view':navigate(button.dataset.view);break;
    case 'close':closeModal();break;
    case 'edit-character':editCharacter();break;
    case 'equipment':case 'features':editSimple(a);break;
    case 'resources':editResources();break;
    case 'conditions':editConditions();break;
    case 'hp':{
      ui.hpAmount=Number($('#hp-amount')?.value||ui.hpAmount);let result;const kind=button.dataset.type;
      if(mutate(s=>{result=applyHP(s.character,kind,ui.hpAmount);logAction(s,`${kind==='damage'?'Took':'Healed'} ${ui.hpAmount} HP${result.tempUsed?` (${result.tempUsed} absorbed by temporary HP)`:''}.`);},kind==='damage'?`Applied ${ui.hpAmount} damage`:`Healed ${ui.hpAmount} HP`)){
        if(result.check)openModal('Hold your concentration',`<p>You took damage while concentrating on <strong>${esc(c.concentration)}</strong>. Make a Constitution saving throw, <strong>DC ${result.check}</strong>. War Caster or other effects may change this roll.</p><div class="modal-actions">${action('end-concentration','Failed · end concentration')}${action('close','Passed · keep focus',{type:'primary'})}</div>`);
        else if(result.atZero)toast('At zero HP. Concentration ended; review unconsciousness, death saves and massive damage with your DM.');
      }break;}
    case 'temp-hp':openModal('Temporary hit points',`<form id="temp-form"><p>Temporary HP do not stack. Keep the higher value.</p>${field('amount','Temporary HP to gain',5,'number','min="1" max="9999" required')}${footer('Apply temporary HP')}</form>`);break;
    case 'inspiration':mutate(s=>{s.character.inspiration=!s.character.inspiration;logAction(s,s.character.inspiration?'Gained Heroic Inspiration.':'Used Heroic Inspiration.');});break;
    case 'end-concentration':mutate(s=>{logAction(s,`Ended concentration on ${s.character.concentration}.`);s.character.concentration='';},'Concentration ended');if($('#modal').open)closeModal();break;
    case 'death':mutate(s=>{const d=s.character.death,t=button.dataset.type,i=Number(button.dataset.index);d[t]=d[t]===i+1?i:i+1;logAction(s,`Death saves: ${d.success} successes, ${d.failure} failures.`);});break;
    case 'slot-pip':mutate(s=>{const slot=s.character.slots.find(s=>s.level===Number(button.dataset.level));const available=slot.max-slot.used;if(Number(button.dataset.index)<available){slot.used++;logAction(s,`Spent a level ${slot.level} spell slot.`);}else{slot.used--;logAction(s,`Restored a level ${slot.level} spell slot.`);}});break;
    case 'resource-pip':mutate(s=>{const r=s.character.resources.find(r=>r.id===id);const spend=Number(button.dataset.index)<r.max-r.used;r.used+=spend?1:-1;logAction(s,`${spend?'Used':'Restored'} ${r.name}.`);});break;
    case 'undo':if(history.length){const old=history.pop();mutate(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,old);logAction(s,'Undid the previous change.');},'Last change undone',{undo:false});restoreDraft();render();}break;
    case 'rest':restDialog();break;
    case 'long-rest':if(c.hp>0){mutate(s=>{longRest(s.character);logAction(s,'Completed a long rest.');},'Rested and ready');closeModal();}break;
    case 'spell-detail':spellDetail(id);break;
    case 'edit-spell':editSpell(id);break;
    case 'new-spell':editSpell('');break;
    case 'delete-spell':confirmDialog('Remove this spell?','This removes it from your spellbook. You can undo this on the character sheet.','confirm-delete-spell','Remove spell',`data-id="${esc(id)}"`);break;
    case 'confirm-delete-spell':mutate(s=>{s.character.spells=s.character.spells.filter(x=>x.id!==id);},'Spell removed');closeModal();break;
    case 'new-session':sessionDialog();break;
    case 'edit-session':sessionDialog(true);break;
    case 'select-session':saveDraft();mutate(s=>{s.activeSession=id;});restoreDraft();render();break;
    case 'edit-note':noteDialog(id);break;
    case 'delete-note':confirmDialog('Remove this note?','This note will be removed from the session and ChatGPT context. You can undo this on the character sheet.','confirm-delete-note','Remove note',`data-id="${esc(id)}"`);break;
    case 'confirm-delete-note':mutate(s=>{const ses=s.sessions.find(x=>x.id===s.activeSession);ses.notes=ses.notes.filter(n=>n.id!==id);},'Note removed');closeModal();break;
    case 'suggest-question':ui.question=button.dataset.question;ui.preparedText='';saveDraft();render();$('#ask-draft')?.focus();break;
    case 'copy-context':try{await navigator.clipboard.writeText(ui.preparedText);toast('Context copied. Paste it into ChatGPT.');button.innerHTML=icon('check')+'Copied';}catch{openModal('Copy your prepared question',`<p>Clipboard access was unavailable. Select and copy the text below, then paste it into ChatGPT.</p><textarea id="manual-copy" readonly style="min-height:250px;font-size:12px">${esc(ui.preparedText)}</textarea><div class="modal-actions"><a class="btn primary" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Open ChatGPT ${icon('external')}</a></div>`);$('#manual-copy').select();}break;
    case 'account':accountDialog();break;
    case 'firebase-config':configDialog();break;
    case 'google-auth':button.disabled=true;try{await cloud.google();closeModal();toast('Signed in to Firebase');}finally{button.disabled=false;}break;
    case 'reset-password':{const email=$('#auth-form [name=email]').value;if(!email)throw new Error('Enter your email first.');await cloud.resetPassword(email);toast('If an account exists, a reset email will be sent.');break;}
    case 'sign-out':await cloud.signOut();closeModal();toast('Signed out. Showing this device’s guest sheet.');break;
    case 'sync-now':if(!cloudReady)throw new Error('Wait for Firebase to load your cloud sheet first.');cloudError='';envelope.pending=true;persist();closeModal();await sync();break;
    case 'bring-guest':confirmDialog('Use your guest sheet?','This replaces the signed-in account’s current sheet with this browser’s guest sheet. A local recovery copy will be kept.','confirm-bring-guest','Use guest sheet');break;
    case 'confirm-bring-guest':{if(!account||!cloudReady)throw new Error('Wait for your Firebase account to finish loading.');const guest=readEnvelope(storagePrefix+'guest');if(!guest)throw new Error('There is no saved guest sheet on this device.');localStorage.setItem(storeKey+':recovery:'+Date.now(),JSON.stringify(envelope));mutate(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,clone(guest.state));},'Guest sheet copied to your account');closeModal();restoreDraft();render();break;}
    case 'keep-local':if(cloudConflict){localStorage.setItem(storeKey+':cloud-recovery:'+Date.now(),JSON.stringify(cloudConflict));envelope.revision=cloudConflict.revision;cloudConflict=null;cloudError='';envelope.pending=true;persist();queueSync();render();}break;
    case 'keep-cloud':if(cloudConflict){localStorage.setItem(storeKey+':recovery:'+Date.now(),JSON.stringify(envelope));state=cloudConflict.state;envelope={state,revision:cloudConflict.revision,pending:false};cloudConflict=null;cloudError='';history=[];persist();restoreDraft();cloudStatus='Synced to Firebase';render();}break;
    case 'export':exportState();break;
    case 'import':openModal('Import a character backup',`<p>Choose a Rivet JSON backup. Your current sheet will be saved as a local recovery copy before replacement.</p><input id="import-file" type="file" accept="application/json,.json" class="file-input" aria-label="Character backup file"><div class="modal-actions">${action('close','Cancel')}</div>`);break;
    case 'confirm-import':if(importedState){localStorage.setItem(storeKey+':recovery:'+Date.now(),JSON.stringify(envelope));const importCopy=clone(importedState);if(mutate(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,importCopy);},'Backup imported')){importedState=null;restoreDraft();closeModal();render();}}break;
    case 'recovery':{const found={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith(storagePrefix)&&!k.endsWith('firebase'))found[k]=localStorage.getItem(k);}download('rivet-device-recovery.json',JSON.stringify(found,null,2));toast('Recovery file downloaded.');break;}
    case 'clear-cache':confirmDialog('Clear this device’s saved data?','Export a backup first. This signs you out and removes all local character saves, drafts and recovery copies from this browser. Your Firebase cloud records are kept.','confirm-clear-cache','Clear this device');break;
    case 'confirm-clear-cache':if(cloud.auth)await cloud.signOut();clearingLocal=true;for(const k of Object.keys(localStorage))if(k.startsWith(storagePrefix)&&k!==storagePrefix+'firebase')localStorage.removeItem(k);location.reload();break;
    case 'print':navigate('sheet');window.print();break;
    case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else openModal('Take Rivet to the table',`<p><strong>iPhone / iPad:</strong> Open this page in Safari. Tap Share, then Add to Home Screen.</p><p><strong>Android:</strong> Open your browser menu and choose Install app or Add to Home screen.</p><p>Load the sheet once while online. Your character and notes will remain available offline on this device. Cloud sync and ChatGPT require internet.</p>`);break;
  }
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;clickAction(button).catch(modalError);});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
async function submitForm(form){const f=new FormData(form),val=k=>String(f.get(k)||'').trim(),num=k=>Number(f.get(k));
  switch(form.id){
    case 'character-form':{
      const succeeded=mutate(s=>{const c=s.character;['name','nickname','species','className','subclass','background','alignment','rules'].forEach(k=>c[k]=val(k));['level','maxHp','hp','tempHp','ac','speed','initiativeBonus','hitDie','maxHitDice','hitDice'].forEach(k=>c[k]=num(k));c.hp=Math.min(c.hp,c.maxHp);c.hitDice=Math.min(c.hitDice,c.maxHitDice);c.spellAbility=val('spellAbility');ABILITIES.forEach(a=>c.abilities[a]=num(a));c.saves=ABILITIES.filter(a=>f.has('save-'+a));c.skills=Object.fromEntries(Object.keys(SKILLS).map(name=>[name,num('skill-'+name)]).filter(([,v])=>v));c.slots=Array.from({length:9},(_,i)=>({level:i+1,max:num('slot-max-'+(i+1)),used:num('slot-used-'+(i+1))})).filter(x=>x.max>0);if(c.hp===0)c.concentration='';s.reviewed=f.has('reviewed');logAction(s,'Updated character details.');},'Character saved');if(succeeded)closeModal();break;}
    case 'equipment-form':if(mutate(s=>{s.character.equipment=val('equipment');s.character.gold=num('gold');},'Pack updated'))closeModal();break;
    case 'features-form':if(mutate(s=>{s.character.features=val('features');s.character.backstory=val('backstory');},'Traits and story saved'))closeModal();break;
    case 'resources-form':if(mutate(s=>{s.character.resources=s.character.resources.flatMap((r,i)=>f.has('r-delete-'+i)?[]:[{...r,name:val('r-name-'+i),max:num('r-max-'+i),used:num('r-used-'+i),reset:val('r-reset-'+i),shortRecovery:num('r-short-'+i)}]);if(val('new-name'))s.character.resources.push({id:uid(),name:val('new-name'),max:num('new-max'),used:0,reset:'long',shortRecovery:0});},'Resources updated'))closeModal();break;
    case 'conditions-form':if(mutate(s=>{const c=s.character;c.conditions=CONDITIONS.filter(x=>f.has('condition-'+x));c.exhaustion=num('exhaustion');c.concentration=val('concentration');if(c.hp===0||c.conditions.some(x=>['Incapacitated','Paralyzed','Petrified','Stunned','Unconscious'].includes(x)))c.concentration='';logAction(s,'Updated conditions and focus.');},'Conditions updated'))closeModal();break;
    case 'temp-form':if(mutate(s=>{applyHP(s.character,'temp',num('amount'));logAction(s,`Temporary HP set to ${s.character.tempHp}.`);},'Temporary HP applied'))closeModal();break;
    case 'short-rest-form':{const count=num('dice');if(!Number.isInteger(count)||count<0||count>state.character.hitDice)throw new Error('Choose an available number of Hit Dice.');const healing=num('healing');if(mutate(s=>{shortRest(s.character,count,healing);logAction(s,`Short rest: spent ${count} Hit Dice, ${healing} healing.`);},'Short rest recorded')){closeModal();}break;}
    case 'cast-form':{const spell=state.character.spells.find(s=>s.id===form.dataset.id);if(!spell||!spell.prepared)throw new Error('Prepare this spell first.');const level=spell.level?num('castLevel'):0;if(spell.level&&level<spell.level)throw new Error('Choose a slot at or above the spell level.');if(mutate(s=>{if(level)spendSlot(s.character,level);if(spell.concentration)s.character.concentration=spell.name;logAction(s,`Cast ${spell.name}${level?' at level '+level:''}.`);},`${spell.name} cast${level?' · level '+level+' slot spent':''}`))closeModal();break;}
    case 'spell-form':{const id=form.dataset.id;const spell={id:id||uid(),name:val('name'),level:num('level'),time:val('time'),range:val('range'),notes:val('notes'),concentration:f.has('concentration'),prepared:f.has('prepared')};if(mutate(s=>{const index=s.character.spells.findIndex(x=>x.id===id);if(index>=0)s.character.spells[index]=spell;else s.character.spells.push(spell);},'Spell saved'))closeModal();break;}
    case 'session-form':{saveDraft();const edit=form.dataset.edit==='true';if(mutate(s=>{if(edit){const ses=s.sessions.find(x=>x.id===s.activeSession);ses.title=val('title');ses.date=val('date');}else{const ses={id:uid(),title:val('title'),date:val('date'),notes:[]};s.sessions.push(ses);s.activeSession=ses.id;}},edit?'Session updated':'New session created')){closeModal();restoreDraft();render();}break;}
    case 'note-form':{const text=ui.noteDraft.trim();if(!text)throw new Error('Write a note first.');if(mutate(s=>s.sessions.find(x=>x.id===s.activeSession).notes.push({id:uid(),text,tag:ui.noteTag,include:true,carry:false,createdAt:Date.now()}),'Note saved')){ui.noteDraft='';saveDraft();render();}break;}
    case 'edit-note-form':if(mutate(s=>{const n=s.sessions.find(x=>x.id===s.activeSession).notes.find(n=>n.id===form.dataset.id);if(!n)throw new Error('This note no longer exists.');n.text=val('text');n.tag=val('tag');},'Note updated'))closeModal();break;
    case 'ask-form':{const q=ui.question.trim();if(!q)throw new Error('Enter a question first.');if(mutate(s=>{s.questions.unshift({id:uid(),text:q,sessionId:s.activeSession,at:Date.now()});s.questions=s.questions.slice(0,20);},null,{undo:false})){ui.preparedText=buildContext(state,q,{includeNotes:ui.includeNotes,concise:ui.concise});render();$('.prepared')?.scrollIntoView({behavior:'smooth',block:'nearest'});}break;}
    case 'auth-form':await cloud.email(val('email'),String(f.get('password')||''),f.has('create'));closeModal();toast('Signed in to Firebase');break;
    case 'config-form':{
      let next;try{next=JSON.parse(val('config'));}catch{throw new Error('Paste a JSON object with double-quoted property names.');}
      if(!next||Array.isArray(next)||typeof next!=='object')throw new Error('Paste your Firebase web configuration object.');
      if(next.private_key||next.client_secret||next.type==='service_account')throw new Error('This is a secret credential. Use only the public Firebase web configuration.');
      for(const k of ['apiKey','projectId','authDomain','appId'])if(typeof next[k]!=='string'||!next[k].trim())throw new Error('Missing '+k+' in Firebase configuration.');
      if(!/^[a-z0-9-]+\.(firebaseapp\.com|web\.app)$/.test(next.authDomain))throw new Error('Use your Firebase project’s firebaseapp.com or web.app authDomain.');
      const allowed=['apiKey','authDomain','projectId','appId','messagingSenderId'];next=Object.fromEntries(allowed.filter(k=>typeof next[k]==='string').map(k=>[k,next[k]]));
      persist();if(cloud.auth)await cloud.signOut();localStorage.setItem(storagePrefix+'firebase',JSON.stringify(next));location.reload();break;}
  }
}
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(!form.matches('form'))return;const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;submitForm(form).catch(modalError).finally(()=>{if(button?.isConnected)button.disabled=false;});});
document.addEventListener('input',event=>{const el=event.target;
  if(el.id==='note-draft'){ui.noteDraft=el.value;saveDraft();}
  if(el.id==='ask-draft'){ui.question=el.value;ui.preparedText='';saveDraft();$('.prepared')?.remove();}
  if(el.id==='hp-amount')ui.hpAmount=Number(el.value);
  if(el.id==='spell-search'){ui.spellSearch=el.value;const spells=state.character.spells.filter(s=>(ui.spellLevel==='all'||s.level===Number(ui.spellLevel))&&(!ui.preparedOnly||s.prepared)&&s.name.toLowerCase().includes(ui.spellSearch.toLowerCase()));$('#spell-results').innerHTML=spellResults(spells);}
});
document.addEventListener('change',async event=>{const el=event.target;
  try{
    if(el.id==='note-tag')ui.noteTag=el.value;
    if(el.id==='spell-level'){ui.spellLevel=el.value;render();}
    if(el.id==='prepared-only'){ui.preparedOnly=el.checked;render();}
    if(el.id==='include-notes'){ui.includeNotes=el.checked;ui.preparedText='';render();}
    if(el.id==='concise'){ui.concise=el.checked;ui.preparedText='';render();}
    if(el.dataset.noteToggle){const key=el.dataset.noteToggle;mutate(s=>{const n=s.sessions.find(x=>x.id===s.activeSession).notes.find(n=>n.id===el.dataset.id);if(n&&['include','carry'].includes(key))n[key]=el.checked;});}
    if(el.id==='import-file'){
      const file=el.files[0];if(!file)return;if(file.size>700000)throw new Error('This backup exceeds the 700 KB import limit.');
      importedState=validateState(JSON.parse(await file.text()));confirmDialog('Replace your current sheet?',`Import <strong>${esc(importedState.character.name)}</strong> and ${importedState.sessions.length} session${importedState.sessions.length===1?'':'s'}? Your current sheet will be retained as a local recovery copy.`,'confirm-import','Import this sheet');
    }
  }catch(error){modalError(error);}
});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['sheet','spells','journal','ask','settings'].includes(v)&&ui.view!==v){ui.view=v;render();}});
window.addEventListener('online',()=>{cloudError='';cloudStatus=account?'Reconnecting…':'Saved on this device';queueSync();renderStatus();});
window.addEventListener('offline',()=>{cloudStatus='Offline · saved here';renderStatus();});
window.addEventListener('storage',event=>{if(event.key!==storeKey||!event.newValue)return;try{const next=JSON.parse(event.newValue);validateState(next.state);if(next.state.updatedAt<=state.updatedAt)return;if(envelope.pending&&account){cloudStatus='Another tab changed this sheet';toast('Another tab changed the sheet. Export your current copy before reloading.');renderStatus();return;}state=next.state;envelope=next;history=[];ui.preparedText='';restoreDraft();render();}catch{toast('Another tab wrote an unreadable save. Your current sheet is still open.');}});
window.addEventListener('pagehide',()=>{persist();saveDraft();});
render();
if('serviceWorker' in navigator&&location.hostname!=='terminal.local')navigator.serviceWorker.register('./sw.js').catch(()=>{toast('Offline install is unavailable in this browser. Local character saving still works.');});
